// A package that runs in Node. Its load has no effects, so the program
// starts Node at the first call.
let calls = 0;
export const kit = {
  count() {
    return ++calls;
  },
  failLater(message) {
    return Promise.reject(new Error(message));
  },
  nextTick(callback) {
    process.nextTick(callback);
  },
  microtask(callback) {
    queueMicrotask(callback);
  },
  // A tick that queues a microtask that queues the tick that calls back.
  tickChain(callback) {
    process.nextTick(() => queueMicrotask(() => process.nextTick(callback)));
  },
};
